-- Israel story arc: 3 stories tracing SHAAM from the genuine no-rejection
-- pilot through full ITA scrutiny powers to the accelerated threshold
-- schedule reaching its permanent floor. Sourced from VATupdate's
-- dedicated Israel briefings, Sovos, EDICOM, and vatit.com, cross-checked
-- against each other for threshold dates and figures.

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2024-05-20-israel-pilot-launch', '2024-05-20', '2024-05', 'Israel''s SHAAM allocation-number system went live for domestic B2B invoices above NIS 25,000, opening with a genuine no-rejection pilot period that gave businesses a low-risk window to build out their submission processes.', '<h3>🇮🇱 Israel''s SHAAM clearance platform goes live</h3>
<p>Israel''s Economic Efficiency Law of 2023 laid the legal groundwork, but it was this month that the SHAAM (allocation-number) platform actually began operating: domestic B2B invoices exceeding NIS 25,000 (excluding VAT) now require a 9-digit allocation number from the Israel Tax Authority (ITA) before the buyer can deduct the input VAT.</p>
<p>Crucially, this launch was a genuine pilot rather than a compliance trap — every valid request received an allocation number automatically, with no rejections for content reasons during this initial period. Businesses could submit either through direct API integration or the ITA''s manual web portal, giving smaller taxpayers a route in without custom development work.</p>
<p>For businesses issuing higher-value domestic B2B invoices, this was the point to start building submission processes in earnest — the scrutiny-free grace period was always going to be temporary, and it was.</p>', 'https://www.gov.il/en/service/request-assignment-number-for-tax-invoice', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2024-05-20-israel-pilot-launch', id FROM countries WHERE name_en = 'Israel';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-05-20-israel-pilot-launch', 'en', 'Israel''s SHAAM clearance platform goes live', 'Israel''s SHAAM allocation-number system went live for domestic B2B invoices above NIS 25,000, opening with a genuine no-rejection pilot period that gave businesses a low-risk window to build out their submission processes.', '<h3>🇮🇱 Israel''s SHAAM clearance platform goes live</h3>
<p>Israel''s Economic Efficiency Law of 2023 laid the legal groundwork, but it was this month that the SHAAM (allocation-number) platform actually began operating: domestic B2B invoices exceeding NIS 25,000 (excluding VAT) now require a 9-digit allocation number from the Israel Tax Authority (ITA) before the buyer can deduct the input VAT.</p>
<p>Crucially, this launch was a genuine pilot rather than a compliance trap — every valid request received an allocation number automatically, with no rejections for content reasons during this initial period. Businesses could submit either through direct API integration or the ITA''s manual web portal, giving smaller taxpayers a route in without custom development work.</p>
<p>For businesses issuing higher-value domestic B2B invoices, this was the point to start building submission processes in earnest — the scrutiny-free grace period was always going to be temporary, and it was.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-05-20-israel-pilot-launch', 'es', 'La plataforma de validación SHAAM de Israel entra en funcionamiento', 'El sistema de números de asignación SHAAM de Israel entró en funcionamiento para las facturas B2B nacionales por encima de 25.000 NIS, comenzando con un auténtico periodo piloto sin rechazos que dio a las empresas una ventana de bajo riesgo para desarrollar sus procesos de envío.', '<h3>🇮🇱 La plataforma de validación SHAAM de Israel entra en funcionamiento</h3>
<p>La Ley de Eficiencia Económica de Israel de 2023 sentó las bases legales, pero fue este mes cuando la plataforma SHAAM (de números de asignación) empezó realmente a funcionar: las facturas B2B nacionales que superan los 25.000 NIS (sin IVA) ahora requieren un número de asignación de 9 dígitos de la Autoridad Tributaria de Israel (ITA) antes de que el comprador pueda deducir el IVA soportado.</p>
<p>Fundamentalmente, este lanzamiento fue un auténtico piloto y no una trampa de cumplimiento — toda solicitud válida recibió un número de asignación automáticamente, sin rechazos por motivos de contenido durante este periodo inicial. Las empresas podían enviar sus facturas mediante integración directa por API o a través del portal web manual de la ITA, dando a los contribuyentes más pequeños una vía de acceso sin necesidad de desarrollo a medida.</p>
<p>Para las empresas que emiten facturas B2B nacionales de mayor valor, este fue el momento de empezar a construir procesos de envío en serio — el periodo de gracia sin escrutinio siempre iba a ser temporal, y lo fue.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-05-20-israel-pilot-launch', 'de', 'Israels SHAAM-Freigabeplattform geht live', 'Israels SHAAM-Zuteilungsnummernsystem ging für inländische B2B-Rechnungen über 25.000 NIS live und startete mit einer echten ablehnungsfreien Pilotphase, die Unternehmen ein risikoarmes Zeitfenster gab, um ihre Einreichungsprozesse aufzubauen.', '<h3>🇮🇱 Israels SHAAM-Freigabeplattform geht live</h3>
<p>Israels Gesetz zur wirtschaftlichen Effizienz von 2023 schuf die rechtliche Grundlage, doch erst in diesem Monat nahm die SHAAM-Plattform (Zuteilungsnummern) tatsächlich den Betrieb auf: Inländische B2B-Rechnungen über 25.000 NIS (ohne Mehrwertsteuer) benötigen nun eine 9-stellige Zuteilungsnummer der israelischen Steuerbehörde (ITA), bevor der Käufer die Vorsteuer abziehen kann.</p>
<p>Entscheidend war, dass dieser Start eine echte Pilotphase und keine Compliance-Falle war — jede gültige Anfrage erhielt automatisch eine Zuteilungsnummer, ohne inhaltliche Ablehnungen während dieser Anfangsphase. Unternehmen konnten entweder per direkter API-Integration oder über das manuelle Webportal der ITA einreichen, was kleineren Steuerzahlern einen Zugang ohne individuelle Entwicklungsarbeit ermöglichte.</p>
<p>Für Unternehmen mit höherwertigen inländischen B2B-Rechnungen war dies der Zeitpunkt, ernsthaft mit dem Aufbau von Einreichungsprozessen zu beginnen — die prüfungsfreie Übergangsfrist war immer als vorübergehend gedacht, und das erwies sich auch so.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-05-20-israel-pilot-launch', 'fr', 'La plateforme de validation SHAAM d''Israël est mise en service', 'Le système de numéros d''allocation SHAAM d''Israël est entré en service pour les factures B2B nationales supérieures à 25 000 NIS, débutant par une véritable période pilote sans rejet qui a offert aux entreprises une fenêtre à faible risque pour bâtir leurs processus de soumission.', '<h3>🇮🇱 La plateforme de validation SHAAM d''Israël est mise en service</h3>
<p>La loi israélienne sur l''efficacité économique de 2023 a posé les bases juridiques, mais c''est ce mois-ci que la plateforme SHAAM (numéros d''allocation) a réellement commencé à fonctionner : les factures B2B nationales dépassant 25 000 NIS (hors TVA) nécessitent désormais un numéro d''allocation à 9 chiffres de l''Autorité fiscale israélienne (ITA) avant que l''acheteur puisse déduire la TVA en amont.</p>
<p>Fait essentiel, ce lancement fut un véritable pilote et non un piège de conformité — toute demande valide a reçu automatiquement un numéro d''allocation, sans rejet pour motif de contenu durant cette période initiale. Les entreprises pouvaient soumettre leurs factures via une intégration API directe ou via le portail web manuel de l''ITA, offrant aux petits contribuables une voie d''accès sans développement sur mesure.</p>
<p>Pour les entreprises émettant des factures B2B nationales de valeur plus élevée, c''était le moment de commencer sérieusement à bâtir des processus de soumission — la période de grâce sans contrôle devait toujours être temporaire, et elle l''a été.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-01-15-israel-enforcement-powers-activate', '2025-01-15', '2025-01', 'Israel''s threshold dropped to NIS 20,000 and the pilot''s no-rejection grace ended: the ITA can now scrutinize submissions and refuse allocation numbers for irregular invoices, with a formal review process available within 2 business days of a refusal.', '<h3>🇮🇱 Israel''s ITA gains real scrutiny and refusal powers</h3>
<p>The SHAAM mandate moved from a soft launch into genuine enforcement this month. The mandatory threshold fell to NIS 20,000, and — more significantly — the Israel Tax Authority stopped issuing allocation numbers automatically for every request. From this point, submissions the ITA deems irregular can be refused outright.</p>
<p>Businesses that receive a refusal aren''t left without recourse: a formal review and hearing process is available within 2 business days. But the practical effect is real — an unresolved refusal means the buyer cannot deduct the input VAT on that invoice, turning data quality in SHAAM submissions into a direct commercial concern rather than a paperwork nicety.</p>
<p>This is also the moment Israel''s enforcement model came into sharper focus: there is still no published, quantified fine schedule for SHAAM non-compliance. Instead, the VAT deduction mechanism itself is doing the enforcement work — a structurally different approach from the escalating-fine models used in several other mandates this tracker covers.</p>', 'https://www.vatupdate.com/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-01-15-israel-enforcement-powers-activate', id FROM countries WHERE name_en = 'Israel';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-15-israel-enforcement-powers-activate', 'en', 'Israel''s ITA gains real scrutiny and refusal powers', 'Israel''s threshold dropped to NIS 20,000 and the pilot''s no-rejection grace ended: the ITA can now scrutinize submissions and refuse allocation numbers for irregular invoices, with a formal review process available within 2 business days of a refusal.', '<h3>🇮🇱 Israel''s ITA gains real scrutiny and refusal powers</h3>
<p>The SHAAM mandate moved from a soft launch into genuine enforcement this month. The mandatory threshold fell to NIS 20,000, and — more significantly — the Israel Tax Authority stopped issuing allocation numbers automatically for every request. From this point, submissions the ITA deems irregular can be refused outright.</p>
<p>Businesses that receive a refusal aren''t left without recourse: a formal review and hearing process is available within 2 business days. But the practical effect is real — an unresolved refusal means the buyer cannot deduct the input VAT on that invoice, turning data quality in SHAAM submissions into a direct commercial concern rather than a paperwork nicety.</p>
<p>This is also the moment Israel''s enforcement model came into sharper focus: there is still no published, quantified fine schedule for SHAAM non-compliance. Instead, the VAT deduction mechanism itself is doing the enforcement work — a structurally different approach from the escalating-fine models used in several other mandates this tracker covers.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-15-israel-enforcement-powers-activate', 'es', 'La ITA de Israel obtiene poderes reales de control y rechazo', 'El umbral de Israel bajó a 20.000 NIS y terminó el periodo de gracia sin rechazos del piloto: la ITA ahora puede examinar los envíos y rechazar números de asignación para facturas irregulares, con un proceso formal de revisión disponible en un plazo de 2 días hábiles tras un rechazo.', '<h3>🇮🇱 La ITA de Israel obtiene poderes reales de control y rechazo</h3>
<p>El mandato SHAAM pasó de un lanzamiento suave a una aplicación genuina este mes. El umbral obligatorio bajó a 20.000 NIS y, de forma más significativa, la Autoridad Tributaria de Israel dejó de emitir números de asignación automáticamente para toda solicitud. A partir de ahora, los envíos que la ITA considere irregulares pueden ser rechazados directamente.</p>
<p>Las empresas que reciben un rechazo no se quedan sin recurso: hay disponible un proceso formal de revisión y audiencia en un plazo de 2 días hábiles. Pero el efecto práctico es real — un rechazo no resuelto significa que el comprador no puede deducir el IVA soportado de esa factura, convirtiendo la calidad de los datos en los envíos a SHAAM en una preocupación comercial directa y no un mero trámite burocrático.</p>
<p>Este es también el momento en que el modelo de aplicación de Israel se definió con mayor claridad: sigue sin existir un baremo de multas publicado y cuantificado para el incumplimiento de SHAAM. En cambio, el propio mecanismo de deducción del IVA hace el trabajo de aplicación — un enfoque estructuralmente distinto de los modelos de multas escalonadas usados en varios otros mandatos de este seguimiento.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-15-israel-enforcement-powers-activate', 'de', 'Israels ITA erhält echte Prüf- und Ablehnungsbefugnisse', 'Israels Schwelle sank auf 20.000 NIS, und die ablehnungsfreie Übergangsfrist der Pilotphase endete: Die ITA kann Einreichungen nun prüfen und Zuteilungsnummern für unregelmäßige Rechnungen ablehnen, mit einem formellen Überprüfungsverfahren innerhalb von 2 Werktagen nach einer Ablehnung.', '<h3>🇮🇱 Israels ITA erhält echte Prüf- und Ablehnungsbefugnisse</h3>
<p>Die SHAAM-Pflicht bewegte sich diesen Monat von einem sanften Start zu echter Durchsetzung. Die verpflichtende Schwelle sank auf 20.000 NIS, und — bedeutsamer noch — die israelische Steuerbehörde stellte nicht mehr automatisch für jede Anfrage eine Zuteilungsnummer aus. Ab diesem Zeitpunkt können als unregelmäßig eingestufte Einreichungen direkt abgelehnt werden.</p>
<p>Unternehmen, die eine Ablehnung erhalten, stehen nicht ohne Rechtsmittel da: Ein formelles Überprüfungs- und Anhörungsverfahren ist innerhalb von 2 Werktagen verfügbar. Doch die praktische Auswirkung ist real — eine ungelöste Ablehnung bedeutet, dass der Käufer die Vorsteuer aus dieser Rechnung nicht abziehen kann, was die Datenqualität bei SHAAM-Einreichungen zu einem direkten geschäftlichen Anliegen statt einer bloßen Formsache macht.</p>
<p>Dies ist auch der Moment, in dem sich Israels Durchsetzungsmodell schärfer abzeichnete: Es gibt weiterhin keinen veröffentlichten, bezifferten Bußgeldkatalog für die Nichteinhaltung von SHAAM. Stattdessen leistet der Vorsteuerabzugsmechanismus selbst die Durchsetzungsarbeit — ein strukturell anderer Ansatz als die Modelle mit eskalierenden Bußgeldern, die bei mehreren anderen Mandaten in diesem Tracker verwendet werden.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-15-israel-enforcement-powers-activate', 'fr', 'L''ITA israélienne obtient de véritables pouvoirs de contrôle et de refus', 'Le seuil israélien est tombé à 20 000 NIS et la période de grâce sans rejet du pilote a pris fin : l''ITA peut désormais examiner les soumissions et refuser des numéros d''allocation pour des factures irrégulières, avec une procédure formelle de révision disponible dans un délai de 2 jours ouvrés après un refus.', '<h3>🇮🇱 L''ITA israélienne obtient de véritables pouvoirs de contrôle et de refus</h3>
<p>L''obligation SHAAM est passée ce mois-ci d''un lancement en douceur à une application véritable. Le seuil obligatoire est tombé à 20 000 NIS et, plus significativement, l''Autorité fiscale israélienne a cessé de délivrer automatiquement un numéro d''allocation pour chaque demande. À partir de ce moment, les soumissions jugées irrégulières par l''ITA peuvent être purement et simplement refusées.</p>
<p>Les entreprises qui reçoivent un refus ne sont pas sans recours : une procédure formelle de révision et d''audience est disponible dans un délai de 2 jours ouvrés. Mais l''effet pratique est réel — un refus non résolu signifie que l''acheteur ne peut pas déduire la TVA en amont sur cette facture, transformant la qualité des données des soumissions SHAAM en une préoccupation commerciale directe plutôt qu''une simple formalité administrative.</p>
<p>C''est aussi le moment où le modèle d''application d''Israël s''est précisé : il n''existe toujours aucun barème d''amendes publié et chiffré pour la non-conformité à SHAAM. C''est plutôt le mécanisme de déduction de la TVA lui-même qui assure le travail d''application — une approche structurellement différente des modèles d''amendes progressives utilisés dans plusieurs autres mandats couverts par ce suivi.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-15-israel-permanent-threshold-floor', '2026-06-15', '2026-06', 'Israel reached the end of its accelerated SHAAM rollout: the threshold hit its permanent floor of NIS 5,000 in June 2026, roughly 18 months ahead of the five-year schedule originally legislated in 2023.', '<h3>🇮🇱 Israel completes its accelerated SHAAM rollout at NIS 5,000</h3>
<p>Israel''s SHAAM threshold reached NIS 5,000 (excluding VAT) — its final, permanent floor, with no further reductions currently scheduled. This closes out an acceleration announced in December 2025 (VAT Implementation Order 01/2025), which compressed what was originally a five-year rollout running through 2028 into just two years.</p>
<p>Along the way, the threshold skipped a planned NIS 15,000 step entirely, dropping straight from NIS 20,000 to NIS 10,000 in January 2026 before reaching NIS 5,000 mid-year. The result is that the large majority of domestic B2B invoices in Israel now require a valid allocation number before the buyer can deduct the input VAT.</p>
<p>Israel''s mandate remains narrower in scope than most CTC systems in this tracker — B2C, B2G, and cross-border transactions are still explicitly excluded — but for domestic B2B trade, this milestone marks the point where SHAAM stopped being a threshold most businesses could plan around and became, in practice, close to universal.</p>', 'https://www.vatupdate.com/2026/06/20/israel-tightens-real-time-invoice-validation-with-lower-threshold-requirement/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-06-15-israel-permanent-threshold-floor', id FROM countries WHERE name_en = 'Israel';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-15-israel-permanent-threshold-floor', 'en', 'Israel completes its accelerated SHAAM rollout at NIS 5,000', 'Israel reached the end of its accelerated SHAAM rollout: the threshold hit its permanent floor of NIS 5,000 in June 2026, roughly 18 months ahead of the five-year schedule originally legislated in 2023.', '<h3>🇮🇱 Israel completes its accelerated SHAAM rollout at NIS 5,000</h3>
<p>Israel''s SHAAM threshold reached NIS 5,000 (excluding VAT) — its final, permanent floor, with no further reductions currently scheduled. This closes out an acceleration announced in December 2025 (VAT Implementation Order 01/2025), which compressed what was originally a five-year rollout running through 2028 into just two years.</p>
<p>Along the way, the threshold skipped a planned NIS 15,000 step entirely, dropping straight from NIS 20,000 to NIS 10,000 in January 2026 before reaching NIS 5,000 mid-year. The result is that the large majority of domestic B2B invoices in Israel now require a valid allocation number before the buyer can deduct the input VAT.</p>
<p>Israel''s mandate remains narrower in scope than most CTC systems in this tracker — B2C, B2G, and cross-border transactions are still explicitly excluded — but for domestic B2B trade, this milestone marks the point where SHAAM stopped being a threshold most businesses could plan around and became, in practice, close to universal.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-15-israel-permanent-threshold-floor', 'es', 'Israel completa su despliegue acelerado de SHAAM en 5.000 NIS', 'Israel llegó al final de su despliegue acelerado de SHAAM: el umbral alcanzó su suelo permanente de 5.000 NIS en junio de 2026, unos 18 meses antes del calendario de cinco años legislado originalmente en 2023.', '<h3>🇮🇱 Israel completa su despliegue acelerado de SHAAM en 5.000 NIS</h3>
<p>El umbral de SHAAM en Israel alcanzó los 5.000 NIS (sin IVA) — su suelo final y permanente, sin más reducciones previstas por ahora. Esto cierra una aceleración anunciada en diciembre de 2025 (Orden de Aplicación del IVA 01/2025), que comprimió en solo dos años lo que originalmente era un despliegue de cinco años previsto hasta 2028.</p>
<p>Por el camino, el umbral se saltó por completo el escalón de 15.000 NIS previsto, bajando directamente de 20.000 NIS a 10.000 NIS en enero de 2026 antes de alcanzar los 5.000 NIS a mitad de año. El resultado es que la gran mayoría de las facturas B2B nacionales en Israel ahora requieren un número de asignación válido antes de que el comprador pueda deducir el IVA soportado.</p>
<p>El mandato de Israel sigue teniendo un alcance más reducido que la mayoría de los sistemas CTC de este seguimiento — las operaciones B2C, B2G y transfronterizas siguen quedando explícitamente excluidas — pero para el comercio B2B nacional, este hito marca el momento en que SHAAM dejó de ser un umbral que la mayoría de las empresas podían planificar con margen y se convirtió, en la práctica, en algo casi universal.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-15-israel-permanent-threshold-floor', 'de', 'Israel schließt den beschleunigten SHAAM-Rollout bei 5.000 NIS ab', 'Israel erreichte das Ende seines beschleunigten SHAAM-Rollouts: Die Schwelle erreichte im Juni 2026 ihre dauerhafte Untergrenze von 5.000 NIS — rund 18 Monate früher als im ursprünglich 2023 gesetzlich vorgesehenen Fünfjahresplan.', '<h3>🇮🇱 Israel schließt den beschleunigten SHAAM-Rollout bei 5.000 NIS ab</h3>
<p>Israels SHAAM-Schwelle erreichte 5.000 NIS (ohne Mehrwertsteuer) — ihre endgültige, dauerhafte Untergrenze, wobei derzeit keine weiteren Absenkungen geplant sind. Damit endet eine im Dezember 2025 angekündigte Beschleunigung (Mehrwertsteuer-Durchführungsverordnung 01/2025), die den ursprünglich bis 2028 laufenden fünfjährigen Rollout auf nur zwei Jahre verkürzte.</p>
<p>Auf dem Weg dorthin übersprang die Schwelle die geplante Stufe von 15.000 NIS vollständig und sank im Januar 2026 direkt von 20.000 NIS auf 10.000 NIS, bevor sie zur Jahresmitte 5.000 NIS erreichte. Das Ergebnis: Die große Mehrheit der inländischen B2B-Rechnungen in Israel benötigt nun eine gültige Zuteilungsnummer, bevor der Käufer die Vorsteuer abziehen kann.</p>
<p>Israels Pflicht bleibt in ihrem Anwendungsbereich enger gefasst als die meisten CTC-Systeme in diesem Tracker — B2C-, B2G- und grenzüberschreitende Transaktionen bleiben weiterhin ausdrücklich ausgenommen — doch für den inländischen B2B-Handel markiert dieser Meilenstein den Punkt, an dem SHAAM aufhörte, eine Schwelle zu sein, mit der die meisten Unternehmen planen konnten, und in der Praxis nahezu universell wurde.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-15-israel-permanent-threshold-floor', 'fr', 'Israël achève son déploiement accéléré de SHAAM à 5 000 NIS', 'Israël a atteint la fin de son déploiement accéléré de SHAAM : le seuil a atteint son plancher permanent de 5 000 NIS en juin 2026, environ 18 mois avant le calendrier de cinq ans initialement légiféré en 2023.', '<h3>🇮🇱 Israël achève son déploiement accéléré de SHAAM à 5 000 NIS</h3>
<p>Le seuil SHAAM d''Israël a atteint 5 000 NIS (hors TVA) — son plancher final et permanent, aucune nouvelle baisse n''étant actuellement prévue. Cela clôt une accélération annoncée en décembre 2025 (arrêté d''application de la TVA 01/2025), qui a comprimé en seulement deux ans ce qui était initialement un déploiement sur cinq ans prévu jusqu''en 2028.</p>
<p>En chemin, le seuil a entièrement sauté l''étape de 15 000 NIS prévue, passant directement de 20 000 NIS à 10 000 NIS en janvier 2026 avant d''atteindre 5 000 NIS en milieu d''année. Résultat : la grande majorité des factures B2B nationales en Israël nécessitent désormais un numéro d''allocation valide avant que l''acheteur puisse déduire la TVA en amont.</p>
<p>Le mandat israélien reste d''une portée plus restreinte que la plupart des systèmes CTC de ce suivi — les opérations B2C, B2G et transfrontalières restent explicitement exclues — mais pour le commerce B2B national, cette étape marque le moment où SHAAM a cessé d''être un seuil que la plupart des entreprises pouvaient anticiper pour devenir, en pratique, presque universel.</p>');
